//! Generate core's Unicode Alphabetic and Alphanumeric property intervals.
//! Run `cargo run -p flux-sourcegen --example unicode` with the selected
//! toolchain, or add `-- --check` to verify the committed tables.
use std::fmt::Write;

pub fn generate() -> String {
    let version = char::UNICODE_VERSION;
    let mut output = format!(
        "// Generated by crates/flux-sourcegen/examples/unicode.rs.\n// Unicode {}.{}.{}, from the selected Rust toolchain.\n\npub const UNICODE_VERSION: (u8, u8, u8) = ({}, {}, {});\n\n",
        version.0, version.1, version.2, version.0, version.1, version.2
    );
    let mut intervals = Vec::new();
    let mut start = 0;
    let mut previous = 0;
    for code in 0..=0x110000 {
        let flags = char::from_u32(code).map_or(0, |c| {
            u8::from(c.is_alphabetic()) | (u8::from(c.is_alphanumeric()) << 1)
        });
        if flags != previous {
            if previous != 0 {
                intervals.push((start, code - 1, previous));
            }
            start = code;
            previous = flags;
        }
    }
    writeln!(
        output,
        "const PROPERTIES: [(u32, u32, u8); {}] = [",
        intervals.len()
    )
    .unwrap();
    for (start, end, flags) in intervals {
        writeln!(output, "    (0x{start:x}, 0x{end:x}, {flags}),").unwrap();
    }
    output.push_str("];\n\npub(crate) fn has_property(c: char, mask: u8) -> bool {\n    let code = c as u32;\n    let mut low = 0;\n    let mut high = PROPERTIES.len();\n    while low < high {\n        let mid = low + (high - low) / 2;\n        let (start, end, flags) = PROPERTIES[mid];\n        if code < start {\n            high = mid;\n        } else if code > end {\n            low = mid + 1;\n        } else {\n            return flags & mask != 0;\n        }\n    }\n    false\n}\n");
    output
}

fn main() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../library/core/src/char_properties.rs");
    let output = generate();
    if std::env::args().any(|arg| arg == "--check") {
        assert_eq!(
            std::fs::read_to_string(&path).unwrap(),
            output,
            "regenerate Unicode tables with the selected toolchain"
        );
    } else {
        std::fs::write(path, output).unwrap();
    }
}
